  if (typeof ctx?.tools?.guard === "function") {
    const classifyBlock = (exec) => {
      const tool = String(exec?.name ?? "");
      const args = exec?.arguments ?? {};
      if (tool === "read") {
        const hasWin = args.offset != null || args.limit != null;
        return hasWin ? null : "read 无 offset/limit 属整读";
